'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var resolve = require( './../lib' );


// MAIN //

bench( format( '%s:shallow', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = {
		'foo': 'bar',
		'baz': 'qux'
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = resolve( doc, '/foo' );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( out.value !== 'bar' ) {
		b.fail( 'should return expected value' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:deep', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = {
		'a': {
			'b': {
				'c': {
					'd': {
						'e': {
							'f': 42
						}
					}
				}
			}
		}
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = resolve( doc, '/a/b/c/d/e/f' );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( out.value !== 42 ) {
		b.fail( 'should return expected value' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:array', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = {
		'arr': [
			[ 10, 20 ],
			[ 30, 40 ]
		]
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = resolve( doc, '/arr/0/1' );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( out.value !== 20 ) {
		b.fail( 'should return expected value' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:root', pkg ), function benchmark( b ) {
	var doc;
	var out;
	var i;

	doc = {
		'foo': 'bar'
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = resolve( doc, '' );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( out.target !== null ) {
		b.fail( 'should return null target for root' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
